// Open Data Eval — Scorecard v6.0 (leaderboard-first redesign)
// Reads window.SCORECARD_DATA  (generated by eval/metadata_eval.py)
//       window.DATASET_EXTRAS  (generated by eval/build_extras.py — links, samples, annotation inventory)
//       window.METRICS_GUIDE   (hand-written plain-English guide to every score)
// Contract for the last two: docs/scorecard/EXTRAS_SCHEMA.md
// Uses global React + ReactDOM — no bundler required. Styles: index.html (tokens) + scorecard.css (classes).

const { useState, useMemo, useEffect, useRef, useCallback } = React;
const DATA   = window.SCORECARD_DATA || [];
const EXTRAS = (window.DATASET_EXTRAS && typeof window.DATASET_EXTRAS === "object") ? window.DATASET_EXTRAS : {};
const GUIDE  = (window.METRICS_GUIDE  && typeof window.METRICS_GUIDE  === "object") ? window.METRICS_GUIDE  : {};
const REPO_URL = "https://github.com/Varun-Nair/open-data-eval";

// ─── constants ───────────────────────────────────────────────────
// Tier lists mirror MODALITY_PROFILES in eval/metadata_eval.py — the page shows the same tiers the score uses.
