// Leaderboard columns. `kind` drives rendering and sorting; "score" = 0–1 pill, "num" = raw number.
const COLUMNS = [
  { key:"rank",          label:"#",             kind:"rank"  },
  { key:"name",          label:"Dataset",       kind:"name"  },
  { key:"overall",       label:"Overall",       kind:"score" },
  { key:"technical",     label:"Technical",     kind:"score" },
  { key:"scale",         label:"Scale",         kind:"score" },
  { key:"annotation",    label:"Annotation",    kind:"score" },
  { key:"reliability",   label:"Reliability",   kind:"score" },
  { key:"accessibility", label:"Access",        kind:"score" },   // header abbreviates "Accessibility"; tooltip carries the full name
  { key:"tooling",       label:"Tooling",       kind:"score" },
  { key:"fit",           label:"Fit",           kind:"score" },
  { key:"hrs",           label:"Hours",         kind:"num"   },
  { key:"envDivCount",   label:"Envs",          kind:"num"   },
  { key:"demoParts",     label:"People",        kind:"num"   },
];
const NUMERIC_COLS = COLUMNS.filter(c => c.kind === "score" || c.kind === "num").map(c => c.key);

// Neutral copy used only when METRICS_GUIDE is missing or still a stub.
const FALLBACK_TIPS = {
  overall:     "Mean of the five dimension scores (Technical, Scale, Annotation, Accessibility, Tooling), ignoring missing ones. Fit is not included.",
  reliability: "Mean of camera-calibration quality and annotation coverage.",
  rank:        "Position by Overall score. Stays fixed whichever column you sort by.",
  hrs:         "Total recorded footage in hours, as reported by the dataset.",
  envDivCount: "Number of distinct recording environments or sites.",
  demoParts:   "Number of distinct participants (camera wearers).",
};

// ─── hooks ───────────────────────────────────────────────────────
function useIsMobile() {
  const [mob, setMob] = useState(window.innerWidth <= 720);
  useEffect(() => {
    const h = () => setMob(window.innerWidth <= 720);
    window.addEventListener("resize", h);
    return () => window.removeEventListener("resize", h);
  }, []);
  return mob;
}

// Hash routing: #leaderboard · #dataset/<encodeURIComponent(name)> · #compare
function parseHash(h) {
  const raw = (h == null ? window.location.hash : h).replace(/^#\/?/, "");
  if (raw.indexOf("dataset/") === 0) {
    let name = raw.slice("dataset/".length);
    try { name = decodeURIComponent(name); } catch (e) { /* keep raw */ }
    return { view: "dataset", name };
  }
  if (raw === "compare") return { view: "compare", name: null };
  return { view: "leaderboard", name: null };
}
function hashFor(view, name) {
  return view === "dataset" ? `#dataset/${encodeURIComponent(name)}` : `#${view}`;
}
function useHashRoute() {
  const [route, setRoute] = useState(() => parseHash());
  useEffect(() => {
    const onChange = () => setRoute(parseHash());
    window.addEventListener("hashchange", onChange);
    window.addEventListener("popstate", onChange);
    return () => {
      window.removeEventListener("hashchange", onChange);
      window.removeEventListener("popstate", onChange);
    };
  }, []);
  const navigate = useCallback((view, name, opts) => {
    const hash = hashFor(view, name);
    if (window.location.hash !== hash) {
      if (opts && opts.replace) window.history.replaceState(null, "", hash);
      else                      window.history.pushState(null, "", hash);
    }
    setRoute(parseHash(hash));
  }, []);
  return [route, navigate];
}

// ─── helpers ─────────────────────────────────────────────────────
function avg(vals) {
  const nonNull = vals.filter(v => v != null);
  if (!nonNull.length) return null;
  return Math.round(nonNull.reduce((a, b) => a + b, 0) / nonNull.length * 1000) / 1000;
}
function scoreColor(v) {
  if (v == null) return "var(--c-null)";
  if (v >= 0.7)  return "var(--c-green)";
  if (v >= 0.4)  return "var(--c-amber)";
  return "var(--c-red)";
}
function scoreBg(v) {
  if (v == null) return "var(--c-track)";
  if (v >= 0.7)  return "var(--c-green-bg)";
  if (v >= 0.4)  return "var(--c-amber-bg)";
  return "var(--c-red-bg)";
}
function scoreTone(v) {
  if (v == null) return "n";
  if (v >= 0.7)  return "g";
  if (v >= 0.4)  return "a";
  return "r";
}
function completenessColor(v) {
  if (v == null) return "var(--c-null)";
  if (v >= 0.8)  return "var(--c-green)";
  if (v >= 0.55) return "var(--c-amber)";
  return "var(--c-red)";
}
function fmtPct(v) { return v == null ? "—" : `${Math.round(v * 100)}`; }
function fmtNum(v) {
  if (v == null) return "—";
  const n = Number(v);
  if (isNaN(n)) return "—";
  if (n >= 10000) return `${Math.round(n / 1000)}k`;
  if (n >= 1000)  return `${(n / 1000).toFixed(1)}k`;
  return Math.round(n).toString();
}
function fmtHours(h) {
  if (h == null) return "—";
  const n = Number(h);
  if (isNaN(n)) return "—";
  if (n >= 10000) return `${Math.round(n / 1000)}k h`;
  if (n >= 1000)  return `${(n / 1000).toFixed(1)}k h`;
  if (n >= 10)    return `${Math.round(n)} h`;
  return `${Math.round(n * 10) / 10} h`;
}
function ordinal(n) { return n === 1 ? "1st" : n === 2 ? "2nd" : n === 3 ? "3rd" : `${n}th`; }
function overallOf(d)     { return avg(DIMS.map(dim => dim.compute(d))); }
function reliabilityOf(d) { return avg([d.camCal, d.annCov]); }
function extrasOf(d) {
  const e = d && EXTRAS[d.name];
  return e && typeof e === "object" ? e : null;
}
function linksOf(d) {
  const e = extrasOf(d);
  return e && e.links && typeof e.links === "object" ? e.links : {};
}
// Python collapses "Depth (RGB-D)" / "Depth (Stereo)" into one "Depth" key — mirror that when matching tiers.
function hasModality(present, item) {
  if (item === "Depth") { for (const m of present) if (typeof m === "string" && m.indexOf("Depth") === 0) return true; return false; }
  return present.has(item);
}

// METRICS_GUIDE accessors — every one tolerates a missing or stub guide.
function clean(s) {
  if (typeof s !== "string") return null;
  const t = s.trim();
  if (!t || /^STUB\b/i.test(t)) return null;
  return t;
}
function guideDim(key) {
  const arr = Array.isArray(GUIDE.dimensions) ? GUIDE.dimensions : [];
  return arr.find(g => g && g.key === key) || null;
}
function guideMetric(field) {
  const m = GUIDE.metrics && GUIDE.metrics[field];
  return m && typeof m === "object" ? m : null;
}
function guideUsecase(key) {
  const u = GUIDE.usecases && GUIDE.usecases[key];
  return u && typeof u === "object" ? u : null;
}
// Tooltip for a per-metric score on the dataset page (fps, res, camCal, annCov, lic, acc, dl, doc, scale, …).
function metricTip(field) {
  const m = guideMetric(field);
  const short = m && clean(m.short);
  if (!short) return null;
  const unit = m.unit && m.unit !== "—" ? ` · ${m.unit}` : "";
  return { title: m.label ? `${m.label}${unit}` : null, text: short };
}
// Tooltip for a dimension (table column / breakdown bar); falls back to the DIMS description.
function dimTip(key) {
  const g = guideDim(key);
  const short = g && clean(g.short);
  if (short) return { title: g.label || (DIM_BY_KEY[key] && DIM_BY_KEY[key].label) || key, text: short };
  if (key === "overall")     return { title: "Overall",     text: FALLBACK_TIPS.overall };
  if (key === "reliability") return { title: "Reliability", text: FALLBACK_TIPS.reliability };
  const dim = DIM_BY_KEY[key];
  return dim ? { title: dim.label, text: dim.desc } : null;
}
function overallTip() {
  const o = GUIDE.overall;
  const short = o && clean(o.short);
  return { title: (o && o.label) || "Overall", text: short || FALLBACK_TIPS.overall };
}
function usecaseTip(uc) {
  const g = guideUsecase(uc.key);
  const short = g && clean(g.short);
  return { title: `Fit · ${(g && g.label) || uc.label}`, text: short || uc.desc };
}
function columnTip(col, uc) {
  switch (col.key) {
    case "overall":     return overallTip();
    case "fit":         return usecaseTip(uc);
    case "rank":        return { title: "Rank", text: FALLBACK_TIPS.rank };
    case "name":        return null;
    case "hrs":         return metricTip("scale")   || { title: "Hours",  text: FALLBACK_TIPS.hrs };
    case "envDivCount": return metricTip("envDiv")  || { title: "Environments", text: FALLBACK_TIPS.envDivCount };
    case "demoParts":   return metricTip("demoDiv") || { title: "Participants", text: FALLBACK_TIPS.demoParts };
    default:            return dimTip(col.key);
  }
}

// ─── ranking (computed once; DATA is static) ─────────────────────
// What a missing dimension means in the data, for the "k of 5 dims" tooltip.
const MISSING_DIM_REASON = {
  technical:     "frame rate and resolution unknown",
  scale:         "hours unknown",
  annotation:    "annotation coverage unknown",
  accessibility: "license and access level unknown",
  tooling:       "dataloader and documentation unknown",
};
// A dataset is "complete" when all five dimensions are non-null. Overall is still the mean of the
// dimensions that exist, so an incomplete dataset can post a high Overall — it just cannot outrank
// complete ones (see rankCompare).
function dimStatus(d) {
  const missing = DIMS.filter(dim => dim.compute(d) == null).map(dim => dim.key);
  return { present: DIMS.length - missing.length, total: DIMS.length, missing, complete: missing.length === 0 };
}
const BASE_ROWS = DATA.map(d => {
  const st = dimStatus(d);
  return {
    d, name: d.name,
    overall:       overallOf(d),
    technical:     DIM_BY_KEY.technical.compute(d),
    scale:         DIM_BY_KEY.scale.compute(d),
    annotation:    DIM_BY_KEY.annotation.compute(d),
    reliability:   reliabilityOf(d),
    accessibility: DIM_BY_KEY.accessibility.compute(d),
    tooling:       DIM_BY_KEY.tooling.compute(d),
    hrs:           d.hrs,
    envDivCount:   d.envDivCount,
    demoParts:     d.demoParts,
    dimsPresent:   st.present,
    missingDims:   st.missing,
    complete:      st.complete,
  };
});
// Overall ranking: complete datasets first (Overall desc, ties → hours desc → name), then incomplete
// datasets ordered by Overall desc among themselves. Null Overall last within its group.
function rankCompare(a, b) {
  if (a.complete !== b.complete) return a.complete ? -1 : 1;
  if (a.overall == null && b.overall == null) return a.name.localeCompare(b.name);
  if (a.overall == null) return 1;
  if (b.overall == null) return -1;
  return (b.overall - a.overall) || ((b.hrs || 0) - (a.hrs || 0)) || a.name.localeCompare(b.name);
}
const RANKED = [...BASE_ROWS].sort(rankCompare);
const RANK_OF = new Map(RANKED.map((r, i) => [r.name, i + 1]));
const ROW_OF  = new Map(BASE_ROWS.map(r => [r.name, r]));

// Top-3 per column using competition ranking (1,1,3). A tie group larger than three gets no medal:
// there is no meaningful "top three" when fifteen datasets share 100.
function medalMap(rows, key) {
  const vals = rows.filter(r => r[key] != null);
  const out = new Map();
  vals.forEach(r => {
    const v = r[key];
    const rank = vals.filter(o => o[key] > v).length + 1;
    if (rank > 3) return;
    const tied = vals.filter(o => o[key] === v).length;
    if (tied <= 3) out.set(r.name, rank);
  });
  return out;
}
function sortRows(rows, sort) {
  const m = sort.dir === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    if (sort.key === "name") return m * a.name.localeCompare(b.name);
    // Rank and Overall both follow the ranking order (complete datasets first), so the default
    // view is exactly the leaderboard order; "asc" simply reverses it.
    if (sort.key === "rank" || sort.key === "overall") return (sort.key === "rank" ? m : -m) * (RANK_OF.get(a.name) - RANK_OF.get(b.name));
    const av = a[sort.key], bv = b[sort.key];
    if (av == null && bv == null) return a.name.localeCompare(b.name);
    if (av == null) return 1;
    if (bv == null) return -1;
    return (m * (av - bv)) || a.name.localeCompare(b.name);
  });
}

